// Request format the iOS app sends to POST /coach, plus validation.
// Limits are deliberately tight: the proxy only exists to serve short coach chats.

export type CoachRole = "user" | "assistant";

export interface CoachTurn {
  role: CoachRole;
  text: string;
  /** App-written description of the table when this user turn was sent (user turns only). */
  context?: string;
}

export interface CoachRequest {
  /** Random install id generated by the app; used only for rate limiting. */
  deviceId: string;
  /** Whole conversation so far, oldest first, ending with the new user turn. */
  turns: CoachTurn[];
}

export const LIMITS = {
  maxBodyBytes: 64_000,
  maxTurns: 24,
  maxUserChars: 1_500,
  maxAssistantChars: 4_000,
  maxContextChars: 6_000,
  maxTotalChars: 48_000,
} as const;

export class RequestError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

const DEVICE_ID = /^[A-Za-z0-9-]{8,64}$/;

/** Validates untrusted JSON into a CoachRequest, or throws RequestError (400). */
export function parseCoachRequest(body: unknown): CoachRequest {
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    throw new RequestError(400, "bad_request", "Body must be a JSON object.");
  }
  const { deviceId, turns } = body as Record<string, unknown>;
  if (typeof deviceId !== "string" || !DEVICE_ID.test(deviceId)) {
    throw new RequestError(400, "bad_device_id", "deviceId must be 8 to 64 letters, digits or dashes.");
  }
  if (!Array.isArray(turns) || turns.length === 0) {
    throw new RequestError(400, "bad_turns", "turns must be a non-empty array.");
  }
  if (turns.length > LIMITS.maxTurns) {
    throw new RequestError(400, "too_many_turns", `At most ${LIMITS.maxTurns} turns per request. Start a new chat.`);
  }

  let total = 0;
  const parsed: CoachTurn[] = turns.map((raw, i) => {
    if (typeof raw !== "object" || raw === null) {
      throw new RequestError(400, "bad_turn", `Turn ${i} must be an object.`);
    }
    const { role, text, context } = raw as Record<string, unknown>;
    const expected: CoachRole = i % 2 === 0 ? "user" : "assistant";
    if (role !== expected) {
      throw new RequestError(400, "bad_turn_order", `Turn ${i} must have role "${expected}" (turns alternate, starting with user).`);
    }
    if (typeof text !== "string" || text.trim().length === 0) {
      throw new RequestError(400, "bad_turn_text", `Turn ${i} needs non-empty text.`);
    }
    const limit = role === "user" ? LIMITS.maxUserChars : LIMITS.maxAssistantChars;
    if (text.length > limit) {
      throw new RequestError(400, "turn_too_long", `Turn ${i} is longer than ${limit} characters.`);
    }
    let ctx: string | undefined;
    if (context !== undefined && context !== null) {
      if (role !== "user" || typeof context !== "string") {
        throw new RequestError(400, "bad_context", `Turn ${i}: context must be a string on a user turn.`);
      }
      if (context.length > LIMITS.maxContextChars) {
        throw new RequestError(400, "context_too_long", `Turn ${i}: context is longer than ${LIMITS.maxContextChars} characters.`);
      }
      ctx = context.trim().length > 0 ? context : undefined;
    }
    total += text.length + (ctx?.length ?? 0);
    return ctx === undefined ? { role: role as CoachRole, text } : { role: role as CoachRole, text, context: ctx };
  });

  if (parsed[parsed.length - 1].role !== "user") {
    throw new RequestError(400, "bad_turn_order", "The last turn must be from the user.");
  }
  if (total > LIMITS.maxTotalChars) {
    throw new RequestError(400, "conversation_too_long", "This chat is too long. Start a new one.");
  }
  return { deviceId, turns: parsed };
}

export interface ApiMessage {
  role: CoachRole;
  content: string;
}

/**
 * Turns the conversation into Messages API turns. Each user turn carries the table state it was
 * asked with, rebuilt identically every request so the history stays append-only (good for caching).
 */
export function buildMessages(request: CoachRequest): ApiMessage[] {
  return request.turns.map((turn) => {
    if (turn.role === "user" && turn.context) {
      return { role: "user", content: `<table_state>\n${turn.context}\n</table_state>\n\n${turn.text}` };
    }
    return { role: turn.role, content: turn.text };
  });
}
